tool.command:
        mkdir -p microbiomeprofiler_inputs microbiomeprofiler_outputs ;
        export MICROBIOMEPROFILER_OUTPUT_DIR=\$PWD/microbiomeprofiler_outputs ;
#if $input_table
        cp -f '$input_table' microbiomeprofiler_inputs/annotation_table.tsv ;
        export MICROBIOMEPROFILER_INPUT=\$PWD/microbiomeprofiler_inputs/annotation_table.tsv ;
#end if
        exec R --vanilla -q -e "suppressMessages(library(MicrobiomeProfiler)) ; app <- MicrobiomeProfiler::run_MicrobiomeProfiler() ; shiny::runApp(app, host = '0.0.0.0', port = 8080, launch.browser = FALSE)"

citations.citation:
@misc{yu2024microbiomeprofiler,
            author       = {Yu, Guangchuang},
            title        = {MicrobiomeProfiler: An R package for microbiome functional enrichment analysis},
            year         = {2024},
            journal      = {Journal of Open Source Software},
            publisher    = {The Open Journal},
            doi          = {10.21105/joss.06522}
        }
